import React, { useState } from 'react';

const LoginRegister = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({
    matricula: '',
    correo: '',
    password: '',
    confirmPassword: ''
  });
  const [errors, setErrors] = useState({});
  const [isBlocked, setIsBlocked] = useState(false);
  const [showBlockMessage, setShowBlockMessage] = useState(false);
  const [showInvalidMatricula, setShowInvalidMatricula] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const validateEmail = (email) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  };

  const validatePassword = (password) => {
    const hasUpperCase = /[A-Z]/.test(password);
    const hasNumber = /\d/.test(password);
    const hasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password);
    return password.length >= 8 && hasUpperCase && hasNumber && hasSpecialChar;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = {};

    if (!isLogin) {
      // Validaciones para registro
      if (!formData.matricula) {
        newErrors.matricula = 'La matrícula es requerida';
      } else if (formData.matricula.length < 5) {
        newErrors.matricula = 'Matrícula no válida';
        setShowInvalidMatricula(true);
      }

      if (!formData.correo) {
        newErrors.correo = 'El correo es requerido';
      } else if (!validateEmail(formData.correo)) {
        newErrors.correo = 'Formato de correo inválido';
      }

      if (!formData.password) {
        newErrors.password = 'La contraseña es requerida';
      } else if (!validatePassword(formData.password)) {
        newErrors.password = 'La contraseña debe tener al menos 8 caracteres, 1 mayúscula, 1 número y 1 signo';
      }

      if (!formData.confirmPassword) {
        newErrors.confirmPassword = 'Confirma tu contraseña';
      } else if (formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = 'Las contraseñas no coinciden';
      }
    } else {
      // Validaciones para login
      if (!formData.matricula) {
        newErrors.matricula = 'La matrícula es requerida';
      }

      if (!formData.password) {
        newErrors.password = 'La contraseña es requerida';
      }
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    // Simulación de bloqueo de cuenta
    if (formData.matricula === '12345') {
      setIsBlocked(true);
      setShowBlockMessage(true);
      setTimeout(() => setShowBlockMessage(false), 5000);
      return;
    }

    // Simulación de matrícula no válida
    if (formData.matricula === '99999') {
      setShowInvalidMatricula(true);
      setTimeout(() => setShowInvalidMatricula(false), 5000);
      return;
    }

    // Aquí iría la lógica para enviar los datos al backend
    console.log('Datos enviados:', formData);
    alert(isLogin ? 'Inicio de sesión exitoso' : 'Registro exitoso');
  };

  const toggleMode = () => {
    setIsLogin(!isLogin);
    setFormData({
      matricula: '',
      correo: '',
      password: '',
      confirmPassword: ''
    });
    setErrors({});
    setIsBlocked(false);
    setShowBlockMessage(false);
    setShowInvalidMatricula(false);
  };

  const handleRecoverPassword = () => {
    alert('Funcionalidad de recuperación de contraseña');
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <div className="auth-header">
          <h1>{isLogin ? 'Iniciar Sesión' : 'Registro de Estudiante'}</h1>
          <p>{isLogin ? 'Ingresa a tu cuenta' : 'Crea tu cuenta de estudiante'}</p>
        </div>

        {showBlockMessage && (
          <div className="alert alert-blocked">
            <p>Tu cuenta ha sido bloqueada temporalmente. Intenta nuevamente en 30 minutos.</p>
          </div>
        )}

        {showInvalidMatricula && (
          <div className="alert alert-error">
            <p>Esta matrícula no es válida o no está dada de alta.</p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="auth-form">
          <div className="form-group">
            <label htmlFor="matricula">Matrícula</label>
            <input
              type="text"
              id="matricula"
              name="matricula"
              value={formData.matricula}
              onChange={handleChange}
              className={errors.matricula ? 'error' : ''}
              placeholder="Ingresa tu matrícula"
            />
            {errors.matricula && <span className="error-text">{errors.matricula}</span>}
          </div>

          {!isLogin && (
            <div className="form-group">
              <label htmlFor="correo">Correo Electrónico</label>
              <input
                type="email"
                id="correo"
                name="correo"
                value={formData.correo}
                onChange={handleChange}
                className={errors.correo ? 'error' : ''}
                placeholder="ejemplo@dominio.com"
              />
              {errors.correo && <span className="error-text">{errors.correo}</span>}
            </div>
          )}

          <div className="form-group">
            <label htmlFor="password">Contraseña</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              className={errors.password ? 'error' : ''}
              placeholder={isLogin ? "Ingresa tu contraseña" : "Mín. 8 caracteres, 1 mayúscula, 1 número, 1 signo"}
            />
            {errors.password && <span className="error-text">{errors.password}</span>}
          </div>

          {!isLogin && (
            <div className="form-group">
              <label htmlFor="confirmPassword">Confirmar Contraseña</label>
              <input
                type="password"
                id="confirmPassword"
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                className={errors.confirmPassword ? 'error' : ''}
                placeholder="Confirma tu contraseña"
              />
              {errors.confirmPassword && <span className="error-text">{errors.confirmPassword}</span>}
            </div>
          )}

          <button 
            type="submit" 
            className="submit-btn"
            disabled={isBlocked}
          >
            {isLogin ? 'Iniciar Sesión' : 'Registrarse'}
          </button>

          {isLogin && (
            <div className="recover-password">
              <button type="button" onClick={handleRecoverPassword} className="recover-btn">
                ¿Olvidaste tu contraseña?
              </button>
            </div>
          )}
        </form>

        <div className="toggle-mode">
          <p>
            {isLogin ? '¿No tienes una cuenta?' : '¿Ya tienes una cuenta?'}
            <button type="button" onClick={toggleMode} className="toggle-btn">
              {isLogin ? 'Regístrate' : 'Inicia Sesión'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoginRegister;
